begin;
create temporary table identity_fixture(a uuid,b uuid,m uuid,r uuid);
insert into identity_fixture(a,b,m) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select,update on identity_fixture to authenticated;
insert into auth.users(id,email_confirmed_at,raw_user_meta_data,raw_app_meta_data) select a,now(),'{"full_name":"Identity QA A"}'::jsonb,'{}'::jsonb from identity_fixture union all select b,now(),'{"full_name":"Identity QA B"}'::jsonb,'{}'::jsonb from identity_fixture union all select m,now(),'{"full_name":"Identity QA Moderator"}'::jsonb,'{"role":"moderator"}'::jsonb from identity_fixture;
update public.profiles set full_name='Identity QA A' where id=(select a from identity_fixture);
select set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true) from identity_fixture;
set local role authenticated;
do $$begin begin perform public.sera_identity_start('passport',false);raise exception 'consent bypass';exception when raise_exception then if sqlerrm='consent bypass' then raise;end if;end;end$$;
update identity_fixture set r=(public.sera_identity_start('passport',true)->>'id')::uuid;
do $$begin begin perform public.sera_identity_submit((select r from identity_fixture));raise exception 'missing evidence accepted';exception when raise_exception then if sqlerrm='missing evidence accepted' then raise;end if;end;end$$;
reset role;
insert into storage.objects(bucket_id,name,owner_id,metadata) select 'sera-identity-private',a::text||'/'||r::text||'/evidence',a::text,'{"mimetype":"application/pdf","size":100}' from identity_fixture;
set local role authenticated;
select public.sera_identity_submit((select r from identity_fixture));
do $$begin if (public.sera_identity_status()->>'status')<>'pending' then raise exception 'pending missing';end if;begin perform public.sera_identity_review((select r from identity_fixture),'approved','Forged approval',true);raise exception 'self approval accepted';exception when raise_exception then if sqlerrm='self approval accepted' then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true) from identity_fixture;
set local role authenticated;
do $$begin if exists(select 1 from storage.objects where bucket_id='sera-identity-private' and name=(select a::text||'/'||r::text||'/evidence' from identity_fixture)) then raise exception 'evidence leaked';end if;if exists(select 1 from public.sera_identity_badges(array[(select a from identity_fixture)])) then raise exception 'pending badge leaked';end if;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',m,'role','authenticated')::text,true) from identity_fixture;
set local role authenticated;
select public.sera_identity_evidence_path((select r from identity_fixture));
do $$begin begin perform public.sera_identity_review((select r from identity_fixture),'approved','Identity evidence reviewed',false);raise exception 'unchecked approval accepted';exception when raise_exception then if sqlerrm='unchecked approval accepted' then raise;end if;end;end$$;
select public.sera_identity_review((select r from identity_fixture),'approved','Identity evidence reviewed',true);
reset role;
select set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true) from identity_fixture;
set local role authenticated;
do $$begin if not exists(select 1 from public.sera_identity_badges(array[(select a from identity_fixture)])) then raise exception 'approved badge missing';end if;end$$;
reset role;
update public.profiles set full_name='Changed QA Name' where id=(select a from identity_fixture);
set local role authenticated;
do $$begin if exists(select 1 from public.sera_identity_badges(array[(select a from identity_fixture)])) then raise exception 'name changed badge retained';end if;end$$;
reset role;
update public.profiles set full_name='Identity QA A' where id=(select a from identity_fixture);
set local role authenticated;
do $$begin if exists(select 1 from public.sera_identity_badges(array[(select a from identity_fixture)])) then raise exception 'restored name resurrected badge';end if;if (public.sera_identity_status()->>'status')<>'revoked' then raise exception 'revocation missing';end if;if not exists(select 1 from public.sera_identity_history() where evidence_present) then raise exception 'history missing';end if;end$$;
reset role;
do $$begin if has_function_privilege('authenticated','public.sera_identity_cleanup_candidates()','execute') then raise exception 'cleanup exposed';end if;end$$;
rollback;
select 'PASS: identity evidence isolation, review authority, permanent name-change revocation, consent and cleanup permissions' as result;
